using LittleLeo;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class DieFacesPanel : MonoBehaviour
{
	[SerializeField]
	private DiceFaceInstance2D[] diceFaceInstance2Ds;

	[SerializeField]
	private TextMeshProUGUI tierText;

	public void InitializeDieFaces(Dice die)
	{
		for (int i = 0; i < diceFaceInstance2Ds.Length; i++)
		{
			diceFaceInstance2Ds[i].Initialize(die, die.GetDiceFaces()[i]);
		}
		tierText.SetText(die.DiceTier.GetLocalizedDiceTierWithDie());
		InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
		{
			LayoutRebuilder.ForceRebuildLayoutImmediate(tierText.transform.parent.GetComponent<RectTransform>());
		});
	}
}
